{
  "name": "opencode-ralph-loop",
  "version": "1.0.10",
  "description": "Minimal Ralph Loop plugin for opencode - auto-continues until task completion",
  "main": "src/index.ts",
  "type": "module",
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ralph-loop",
    "ralph-wiggum",
    "ai-agent",
    "auto-continue",
    "iteration-loop"
  ],
  "author": "Charles Feng",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/charfeng1/opencode-ralph-loop"
  },
  "bugs": {
    "url": "https://github.com/charfeng1/opencode-ralph-loop/issues"
  },
  "homepage": "https://github.com/charfeng1/opencode-ralph-loop#readme",
  "files": [
    "src/",
    "commands/",
    "skills/"
  ],
  "engines": {
    "node": ">=18.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": ">=1.0.0",
    "@types/node": "^20.11.0",
    "typescript": "^5.4.0",
    "vitest": "^4.1.6"
  }
}
